inline bool VerifySMParamValue(::flatbuffers::Verifier &verifier, const void *obj, SMParamValue type) {
  switch (type) {
    case SMParamValue::NONE: {
      return true;
    }
    case SMParamValue::SMParamFloat: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::SMParamFloat *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case SMParamValue::SMParamBool: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::SMParamBool *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case SMParamValue::SMParamInt: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::SMParamInt *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case SMParamValue::SMParamTrigger: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::SMParamTrigger *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

inline bool VerifySMParamValueVector(::flatbuffers::Verifier &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<SMParamValue> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifySMParamValue(
        verifier,  values->Get(i), types->GetEnum<SMParamValue>(i))) {
      return false;
    }
  }
  return true;
}

inline void *SMParamValueUnion::UnPack(const void *obj, SMParamValue type, const ::flatbuffers::resolver_function_t *resolver) {
  (void)resolver;
  switch (type) {
    case SMParamValue::SMParamFloat: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::SMParamFloat *>(obj);
      return ptr->UnPack(resolver);
    }
    case SMParamValue::SMParamBool: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::SMParamBool *>(obj);
      return ptr->UnPack(resolver);
    }
    case SMParamValue::SMParamInt: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::SMParamInt *>(obj);
      return ptr->UnPack(resolver);
    }
    case SMParamValue::SMParamTrigger: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::SMParamTrigger *>(obj);
      return ptr->UnPack(resolver);
    }
    default: return nullptr;
  }
}

